import{z as s,x as d,o,c as p,q as t,j as i,D as l,d as a,s as n,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"epoll 的深化","description":"","frontmatter":{"title":"epoll 的深化","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hpc-epoll-deep.md","filePath":"cs/hpc-epoll-deep.md","lastUpdated":1791063341000}'),A={name:"cs/hpc-epoll-deep.md"};function c(m,E,f,O,L,S){const r=d("Mermaid");return o(),p("div",null,[E[2]||(E[2]=t('<h1 id="epoll-的深化" tabindex="-1">epoll 的深化 <a class="header-anchor" href="#epoll-的深化" aria-label="Permalink to &quot;epoll 的深化&quot;">​</a></h1><div class="epigraph"><p>万级连接之后，epoll 的成本不在 wait 本身，而在惊群唤醒、跨核缓存失效与每个事件陪跑的那次系统调用。</p><footer>—— 据 Linux `epoll(7)`、`accept(2)` 手册；Kerrisk, *The Linux Programming Interface* 整理</footer></div><p><a href="/cs/par-roofline-map">上一课</a>给「并行计算模型」收束：点要用实测字节算，脊点 \\(I^{*}=F/B\\) 量化向量化值多少，优化先爬到屋顶再右移强度，work-span 与 roofline 并读——模型给上限与正确性，机器给墙。算力与并行的账翻完，瓶颈移到 I/O 的入口：连接数与事件率继续上升时，事件循环本身成为新的共享点：accept 的惊群、就绪事件的重复唤醒、定时器与线程间唤醒怎么并进同一个循环、就绪连接怎么交给工作线程。本课写这些深化的做法，后课默认事件循环已经可以分片扩展。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>惊群有两处。accept 惊群：多个线程阻塞等新连接，一个连接唤醒所有，只有一个 accept 成功，其余白付一次调度与缓存污染；wait 惊群：多线程 wait 同一 epoll，LT 下同一就绪 fd 还可能唤醒多个等待者。治理谱系有三档：<code>EPOLLEXCLUSIVE</code>（内核 4.5 起）把唤醒降为只叫一个等待者；<code>SO_REUSEPORT</code> 让多个监听套接字共享同一端口，内核按流散列分发，惊群从根上消失，代价是没有全局视图、负载可能不均；<code>EPOLLONESHOT</code> 管交接——就绪 fd 交给工作池处理时，事件一次后自动解除注册，处理完 rearm，把「正在处理」编码进注册状态而不是应用锁。不这么做会错在哪：省掉 ONESHOT，两线程同时读写同一连接的正确性只能靠锁兜底，锁又把分片买来的并行度收了回去。</p><p><span class="marginnote">术语翻译：惊群（thundering herd）就是「门铃一响全楼都醒」——内核把等在同一事件上的线程全叫起来，结果只有一个真有活干，其余白付一次上下文切换和缓存污染。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单核循环的完整形态是把所有异步源收进一张兴趣表：eventfd 收线程间唤醒，timerfd 收定时器，signalfd 收信号，一次 wait 管全部。分片按核切：每核一个 epoll、一个循环；监听端用 SO_REUSEPORT 散列，或共享监听 fd 配 EPOLLEXCLUSIVE。写路径要「按需注册」：只在有数据要写时挂 EPOLLOUT，写空立刻撤注，LT 下不留常亮事件空转；读路径遵守<a href="/cs/socket-nonblock">阻塞与非阻塞套接字</a>的约定，ET 读到 EAGAIN、容忍短写。下游变慢时，背压的真正水位在应用层待写队列，接回<a href="/cs/socket-buffers">套接字缓冲与背压</a>的口径，不能只看内核缓冲。</p>',8)),(o(),i(B,null,{default:l(()=>[n(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20NIC%5B%22%E6%96%B0%E8%BF%9E%E6%8E%A5%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20REUSE%5B%22SO_REUSEPORT%20%E6%B5%81%E6%95%A3%E5%88%97%22%5D%0A%20%20REUSE%20--%3E%20L1%5B%22%E6%A0%B8%201%EF%BC%9A%E7%9B%91%E5%90%AC%20fd%20%2B%20epoll%22%5D%0A%20%20REUSE%20--%3E%20L2%5B%22%E6%A0%B8%202%EF%BC%9A%E7%9B%91%E5%90%AC%20fd%20%2B%20epoll%22%5D%0A%20%20L1%20--%3E%20EV%5B%22eventfd%2Ftimerfd%20%E5%B9%B6%E5%85%A5%E5%90%8C%E4%B8%80%20wait%22%5D%0A%20%20L2%20--%3E%20EV%0A%20%20EV%20--%3E%20OS%5B%22EPOLLONESHOT%20%E8%A7%A3%E9%99%A4%E6%B3%A8%E5%86%8C%22%5D%0A%20%20OS%20--%3E%20POOL%5B%22%E5%B7%A5%E4%BD%9C%E6%B1%A0%E5%A4%84%E7%90%86%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20POOL%20--%3E%20REARM%5B%22%E5%A4%84%E7%90%86%E5%AE%8C%20rearm%20%E5%9B%9E%E5%85%B4%E8%B6%A3%E8%A1%A8%22%5D%0A"})]),fallback:l(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("分片把连接固定到核上：无锁、缓存亲和，代价是失去全局视图——某核分到的连接全是热点流时，只能靠散列重洗或显式迁移连接，迁移本身又是一次 ONESHOT 交接。rearm 是一次 "),e("code",null,"epoll_ctl"),a(" 调用，事件率高时它自己进入成本表；等价替代是工作池处理完毕后再注册，语义相同，差在由谁付这一次调用。EPOLLEXCLUSIVE 只保证「一个事件只唤醒一个等待者」，同一轮多个 fd 都就绪时仍可能有额外唤醒，把它当成「惊群已根除」是常见误读。")],-1)),E[5]||(E[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：以为 LT（水平触发）的「没处理完就一直提醒」是免费保险。套接字几乎恒可写时，常亮的 EPOLLOUT 每轮都报告，事件循环被空转占满——这正是写路径要「写空即撤注」的原因。")],-1)),E[6]||(E[6]=e("p",null,"写路径「按需注册」的一生：",-1)),(o(),i(B,null,{default:l(()=>[n(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%BA%94%E7%94%A8%E8%A6%81%E5%86%99%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20F%7B%22%E5%86%85%E6%A0%B8%E5%8F%91%E9%80%81%E7%BC%93%E5%86%B2%E6%9C%89%E7%A9%BA%E9%97%B4%3F%22%7D%0A%20%20F%20--%20%22%E6%9C%89%2C%20%E4%B8%80%E6%AC%A1%E5%86%99%E5%AE%8C%22%20--%3E%20D1%5B%22%E7%9B%B4%E6%8E%A5%E5%86%99%2C%20%E4%B8%8D%E7%A2%B0%20EPOLLOUT%22%5D%0A%20%20F%20--%20%22%E6%BB%A1%2C%20%E5%87%BA%E7%8E%B0%E7%9F%AD%E5%86%99%22%20--%3E%20D2%5B%22%E6%8C%82%E4%B8%8A%20EPOLLOUT%20%E5%86%8D%E8%B5%B0%22%5D%0A%20%20D2%20--%3E%20N%7B%22epoll%20%E9%80%9A%E7%9F%A5%E5%8F%AF%E5%86%99%3F%22%7D%0A%20%20N%20--%20%22%E6%98%AF%22%20--%3E%20W3%5B%22%E7%BB%A7%E7%BB%AD%E5%86%99%E7%9B%B4%E5%88%B0%E5%86%99%E7%A9%BA%22%5D%0A%20%20W3%20--%3E%20U%5B%22%E7%AB%8B%E5%88%BB%E6%92%A4%E6%B3%A8%20EPOLLOUT%22%5D%0A%20%20N%20--%20%22%E5%90%A6%22%20--%3E%20I%5B%22%E6%9C%AC%E8%BD%AE%E8%B7%B3%E8%BF%87%2C%20%E4%B8%8D%E7%A9%BA%E8%BD%AC%22%5D%0A"})]),fallback:l(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p><span class="marginnote">SO_REUSEPORT 按四元组散列分流，同一连接恒定落同一核；运行期增删监听 fd 会引发连接重分布，重分布的连接被发到新套接字的循环上，应用层要么容忍乱序交接，要么自己做连接迁移。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入提交完成模型，io_uring 是下一课；不写 nginx、Seastar 等框架的实现对照，不写 epoll 对非常规文件类型（部分设备 poll 实现粗糙）的坑。数量级上，单核循环的吞吐由每事件系统调用数决定：每事件两次陷入的模型，事件率上去之后，陷入本身开始排满预算——这正是下一课要从模型层面换掉的假设。</p><p><span class="marginnote">数字实例：每事件若付 2 次系统调用（wait 加 rearm 的 ctl），百万事件每秒就是 200 万次陷入；按每次 1–2 μs 算，仅系统调用就吃掉两三个核的预算——「陷入排满预算」说的就是这个数量级。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>惊群分 accept 与 wait 两处；EPOLLEXCLUSIVE、SO_REUSEPORT 是两条治法，EXCLUSIVE 不等于根除。</li><li>eventfd/timerfd/signalfd 把唤醒、定时、信号并入一个 wait，事件循环才算完整。</li><li>ONESHOT 用注册状态编码「正在处理」，交接不靠应用锁；rearm 的 ctl 调用是高频下的可见成本。</li><li>分片买并行度、卖全局视图；连接迁移是付回来的一笔。</li><li>出处：Linux <code>epoll(7)</code>、<code>accept(2)</code>、<code>socket(7)</code>；Kerrisk, <em>The Linux Programming Interface</em>；Stevens, <em>UNIX Network Programming</em>。</li></ul>',6))])}const h=s(A,[["render",c]]);export{D as __pageData,h as default};
